using DomainModel.Context; using Microsoft.EntityFrameworkCore; namespace DataAccess.Repositories.City; public class CityRepository(ApplicationDbContext c):ICityRepository { public IQueryable<DomainModel.Models.City> Query(bool tracking=false)=>tracking?c.Cities:c.Cities.AsNoTracking(); public Task<DomainModel.Models.City?> GetByIdAsync(int id,bool tracking=true)=>(tracking?c.Cities:c.Cities.AsNoTracking()).FirstOrDefaultAsync(x=>x.CityID==id); public Task<bool> ProvinceExistsAsync(int provinceId)=>c.Provinces.AnyAsync(x=>x.ProvinceID==provinceId); public Task AddAsync(DomainModel.Models.City e)=>c.Cities.AddAsync(e).AsTask(); public void Remove(DomainModel.Models.City e)=>c.Cities.Remove(e); public Task<bool> HasAdvertisementsAsync(int id)=>c.Advertisements.AnyAsync(x=>x.CityID==id); public Task<int> SaveChangesAsync()=>c.SaveChangesAsync(); }
